templates.template:
.wxClanCover { height: 220px; background-size: cover; background-position: center; border-radius: @xf-borderRadiusLarge; margin-bottom: @xf-paddingMedium; }
.wxClanLogo { width: 88px; height: 88px; object-fit: cover; border-radius: @xf-borderRadiusMedium; float: left; margin: 0 @xf-paddingMedium @xf-paddingMedium 0; }
.wxClanTag, .wxClanManagerBanner { color: #fff !important; margin-top: 3px; }

.wxClanProfileMemberships { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.wxClanProfileMembership { display: inline-flex; align-items: center; gap: 5px; padding: 4px 8px; border: 1px solid @xf-borderColor; border-radius: @xf-borderRadiusMedium; background: @xf-contentBg; text-decoration: none; }
.wxClanProfileMembership-tag { font-weight: 700; }

.wxIdentityColor { position: relative; max-width: 520px; }
.wxIdentityColor-line { display: flex; align-items: center; gap: 10px; }
.wxIdentityColor-swatch { width: 38px; height: 38px; border-radius: 50%; border: 2px solid @xf-borderColor; cursor: pointer; box-shadow: 0 0 0 2px @xf-contentBg inset; flex: 0 0 auto; }
.wxIdentityColor-hex { max-width: 160px; font-family: monospace; }
.wxIdentityColor-panel { position: absolute; z-index: 500; top: 46px; left: 0; width: 310px; max-width: calc(100vw - 40px); padding: 14px; background: @xf-contentBg; border: 1px solid @xf-borderColor; border-radius: @xf-borderRadiusLarge; box-shadow: 0 10px 32px rgba(0,0,0,.22); }
.wxIdentityColor-wheel { position: relative; width: 220px; height: 220px; max-width: 100%; aspect-ratio: 1; margin: 0 auto 12px; border-radius: 50%; cursor: crosshair; background: radial-gradient(circle at center, #fff 0%, rgba(255,255,255,0) 72%), conic-gradient(#f00, #ff0, #0f0, #0ff, #00f, #f0f, #f00); touch-action: none; }
.wxIdentityColor-pointer { position: absolute; width: 14px; height: 14px; border: 2px solid #fff; border-radius: 50%; box-shadow: 0 0 0 1px rgba(0,0,0,.55); transform: translate(-50%, -50%); pointer-events: none; }
.wxIdentityColor-brightness { display: grid; grid-template-columns: 80px 1fr; gap: 8px; align-items: center; margin: 8px 0 12px; }
.wxIdentityColor-brightness input { width: 100%; }
.wxIdentityColor-rgb { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.wxIdentityColor-rgb label { display: grid; gap: 4px; font-size: 12px; font-weight: 600; }
.wxIdentityColor-rgb .input { min-width: 0; }

.wxIdentityIcon { display: grid; grid-template-columns: repeat(auto-fill, minmax(42px, 1fr)); gap: 7px; max-width: 520px; }
.wxIdentityIcon-choice { min-height: 40px; padding: 6px; border: 1px solid @xf-borderColor; border-radius: @xf-borderRadiusMedium; background: @xf-contentBg; color: @xf-textColor; cursor: pointer; font-size: 16px; }
.wxIdentityIcon-choice:hover { background: @xf-contentAltBg; }
.wxIdentityIcon-choice.is-selected { border-color: @xf-paletteAccent2; box-shadow: 0 0 0 2px fade(@xf-paletteAccent2, 25%); background: @xf-contentHighlightBg; }

@media (max-width: @xf-responsiveNarrow)
{
    .wxIdentityColor-panel { position: fixed; left: 50%; top: 50%; transform: translate(-50%, -50%); }
}
